




















































import Vue from 'vue'
import ActionConfirmLog from './components/_ActionConfirmLog.vue'
import ActionTitlebar from './components/_ActionTitlebar.vue'
import TechAttack from './components/_TechAttack.vue'

function toTitleCase(str): string {
  str = str.toLowerCase().split(' ')
  for (let i = 0; i < str.length; i++) {
    str[i] = str[i].charAt(0).toUpperCase() + str[i].slice(1)
  }
  return str.join('')
}

export default Vue.extend({
  name: 'cc-combat-dialog',
  components: { ActionTitlebar, ActionConfirmLog, TechAttack },
  props: {
    action: {
      type: Object,
      required: true,
    },
    mech: {
      type: Object,
      required: true,
    },
    pilot: {
      type: Object,
      required: true,
    },
    noAction: { type: Boolean },
    fulltech: { type: Boolean, default: false },
  },
  data() {
    return {
      dialog: false,
      component: null,
      techAttack: false,
      displayLog: false,
      logOverride: [],
    }
  },
  computed: {
    loader() {
      if (!this.action) {
        return null
      }
      const name = toTitleCase(this.action.ID.replace('act_', '').replace('_', ' '))
      var filename : string
      switch (this.action.ID) {
        case 'act_activate_full':
          console.log(`./dialogs/action/_FullActivationDialog.vue`)
          return () => import(`./dialogs/action/_FullActivationDialog.vue`)
        case 'act_jockey':
          console.log(`./dialogs/action/_JockeyDialog.vue`)
          return () => import(`./dialogs/action/_NewJockeyDialog.vue`)
      }
      console.log(`./dialogs/action/_${name}Dialog.vue`)
      return () => import(`./dialogs/action/_${name}Dialog.vue`)
    },
    itemLoader() {
      if (!this.action) {
        return null
      }
      return () => import(`./dialogs/action/_ItemActionDialog.vue`)
    },
  },
  mounted() {
    this.loader()
      .then(() => {
        this.component = () => this.loader()
      })
      .catch(() => {
        this.component = () => this.itemLoader()
      })
    this.techAttack = false
  },
  methods: {
    use(free) {
      if (!this.fulltech){
        this.mech.Pilot.State.CommitAction(this.action, free)
      }
      if (this.action.IsTechAttack) {
        this.techAttack = true
      } 
      else {
        if(this.fulltech){
          this.$emit('fulltech-used', this.action)
          this.hide()
        }
        else{
          this.displayLog = this.action.AnyUsed
          // eslint-disable-next-line @typescript-eslint/no-this-alias
          const self = this
          this.$emit('use', free)
          Vue.nextTick().then(() => self.$forceUpdate())
        }
      }
    },
    undo() {
      this.mech.Pilot.State.UndoAction(this.action)
      this.$emit('undo')
      this.techAttack = false
      this.displayLog = false
      // eslint-disable-next-line @typescript-eslint/no-this-alias
      const self = this
      Vue.nextTick().then(() => self.$forceUpdate())
    },
    techAttackComplete(success) {
      if (this.fulltech) {
        this.techAttack = false

        if (success) this.$emit('add-invade', this.action)
        else this.$emit('add-fail', this.action.Name)

        this.hide()
      } else {
        this.logOverride = ['ВОСХОДЯЩАЯ ЛИНИЯ СВЯЗИ УСТАНОВЛЕНА. ПОПЫТКА УДАЛЕННОГО ДОСТУПА.']
        if (success) {
          this.logOverride.push('ДОСТУП К СИСТЕМЕ ПОЛУЧЕН.')
          this.logOverride = this.logOverride.concat(this.action.Confirm)
        } else this.logOverride.push('ДОСТУП ЗАПРЕЩЕН. СИСТЕМНАЯ ОШИБКА.')
        this.displayLog = true
      }

      // eslint-disable-next-line @typescript-eslint/no-this-alias
      const self = this
      this.$emit('use')
      Vue.nextTick().then(() => self.$forceUpdate())
    },
    show() {
      this.dialog = true
      this.displayLog = this.action.AnyUsed
    },
    hide() {
      if (!this.$refs.c.init) {
        console.log('no init fn', this.$refs.c.name)
      } else {
        this.$refs.c.init()
        this.$refs.log.init()
      }
      this.dialog = false
    },
  },
})
