






























































import Vue from 'vue'
import { Auth } from '@aws-amplify/auth'

export default Vue.extend({
  name: 'auth-password-reset',
  data: () => ({
    loading: false,
    sent: false,
    email: null,
    show: false,
    oldpass: null,
    newpass: null,
    resetpass: null,
    code: null,
    rules: {
      passLength: v => (v && v.length >= 6) || 'Минимум 6 символов',
    },
  }),
  methods: {
    reset() {
      this.loading = true
      Auth.forgotPassword(this.email)
        .then(data => {
          console.log(data)
          this.loading = false
          this.sent = true
        })
        .catch(err => {
          console.log('err at first catch:', err)
          Auth.forgotPassword(this.email.toLowerCase())
            .then(data => {
              console.log(data)
              this.loading = false
              this.sent = true
            })
            .catch(err => {
              console.error(err)
              this.loading = false
              this.sent = false
              this.$notify(`Не получается отправить письмо сброса: ${err.message}`, 'error')
            })
        })
    },
    setNewPassword() {
      this.loading = true
      Auth.forgotPasswordSubmit(this.email, this.code, this.newpass)
        .then(data => {
          console.log(data)
          this.loading = false
          this.$notify('Пароль успешно сменен. Пожалуйста, войдите заново')
          this.$emit('set-state', 'sign-in')
        })
        .catch(err => {
          console.log(err)
          this.$notify(`Не получилось сменить пароль: ${err.message}`, 'error')
          this.loading = false
        })
    },
  },
})
